(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin(x*0.05+y*0.03+t*0.7)*5 + Math.cos(y*0.04-t*0.5)*4;
  const w2y = Math.cos(x*0.04-y*0.05+t*0.6)*5 + Math.sin(x*0.035+t*0.45)*4;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0.7],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.5],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 0.9],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.4],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.8],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.6],
    [60+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1, 0.55],
    [420+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+4)*40, 0.085, 2.4, 0.75]
  ];
  let aS = 0, iS = 0, cS = 0;
  for (const [sX, sY, f, sp, str] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp) * str;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * str;
    cS += Math.sin(d*f*1.3 - t*sp*0.8 + 2.0) * str * 0.5;
  }
  const n = src.length;
  const act = aS/n, inh = iS/n, coupler = cS/n;
  const bg1 = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2 = (Math.sin(sx*0.08-sy*0.06+t*1.5) + Math.cos(sx*0.06+sy*0.09-t*1.3))/2;
  const bg3 = Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg = bg1 + bg2*0.4 + bg3;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const sp2 = Math.sin(dist*0.09-ang*5+t*0.8)*0.2;
  const spiral = sp1 + sp2;
  const rd1 = Math.tanh((act - inh*0.7 + bg*0.3 + spiral)*2.2);
  const rd2 = Math.tanh((act*0.6 + coupler - inh*0.5 + bg*0.2)*1.8);
  const feedback = Math.tanh((rd1 + rd2*0.5 + Math.sin(rd1*rd2*4+t)*0.3)*1.5);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro = Math.sin(sx*0.3+sy*0.25+t*3)*Math.cos(sx*0.2-sy*0.35-t*2.5)*0.15;
  const blend = feedback*0.6 + cell*0.2 + micro*0.2, v = blend*0.5+0.5;
  const pal = [
    [6,12,52],[12,45,88],[18,95,118],[28,155,132],[95,192,108],
    [195,198,62],[228,148,58],[218,82,62],[172,48,78],[118,28,62],[55,16,55],[6,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.85 + Math.sin(feedback*Math.PI)*0.15 + Math.abs(rd1)*0.05;
  const edge = Math.abs(feedback)>0.75?1.2:Math.abs(feedback)>0.5?1.08:1.0;
  const aS2 = Math.sin(ang*2+t*0.3)*0.08;
  return [
    Math.max(0, Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f + aS2*30)*lum*edge)|0)),
    Math.max(0, Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge)|0)),
    Math.max(0, Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f - aS2*30)*lum*edge)|0))
  ];
}
